var fHovering = {
    config : function(){
        if (typeof FLOATING_HOVERING_CONFIG === 'undefined') {
            return {
                active : false,
                delayInitSecond : 0
            }
        }
        return FLOATING_HOVERING_CONFIG
    },
    setStyle : function(el, styleObj){
        Object.entries(styleObj).forEach(([k, v]) => {
            if (v !== null) el.style[k] = v;
        });
    },
    isCapped : function(id, limit) {
        const key = "zm_hovering_click_" + id;
        const count = parseInt(localStorage.getItem(key) || "0", 10);
        return count >= limit;
    },
    setCapped : function(id) {
        const key = "zm_hovering_click_" + id;
        const count = parseInt(localStorage.getItem(key) || "0", 10) + 1;
        localStorage.setItem(key, count);
    },
    createHoveringBanner : function () {
        if(!fHovering.config.active) return;
        const creative = fHovering.config.creatives[Math.floor(Math.random() * fHovering.config.creatives.length)];
        const wrapper = document.createElement("div");
        wrapper.id = "sp-wrapper-hovering-format";
        setStyle(wrapper, {
            position: "fixed",
            zIndex: 9999,
            width: config.width,
            height: config.height,
            top: config.position.top,
            right: config.position.right,
            bottom: config.position.bottom,
            left: config.position.left,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
        });

        const closeBtn = document.createElement("span");
        closeBtn.innerHTML = "&times;";
        setStyle(closeBtn, {
            cursor: "pointer",
            userSelect: "none",
            position: "absolute",
            top: "2px",
            right: "8px",
            background: "rgba(230,230,230,0.9)",
            borderRadius: "50%",
            width: "20px",
            height: "20px",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontWeight: "bold",
            border: "1px solid #ccc",
            zIndex: 10000
        });
        closeBtn.onclick = () => wrapper.remove();
        const imgWrap = document.createElement("div");
        imgWrap.id = "sp-wrapper-hovering-img";
        setStyle(imgWrap, {
            width: "100%",
            height: "100%",
            borderRadius: "0%",
            overflow: "hidden",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            background: "#fff"
        });

        const style = document.createElement("style");
        style.textContent = `@keyframes ring {0% { transform: rotate(0);}1% { transform: rotate(30deg);}3% { transform: rotate(-28deg);}5% { transform: rotate(34deg);}7% { transform: rotate(-32deg);}9% { transform: rotate(30deg);}11% { transform: rotate(-28deg);}13% { transform: rotate(26deg);}15% { transform: rotate(-24deg);}17% { transform: rotate(22deg);}19% { transform: rotate(-20deg);}21% { transform: rotate(18deg);}23% { transform: rotate(-16deg);}25% { transform: rotate(14deg);}27% { transform: rotate(-12deg);}29% { transform: rotate(10deg);}31% { transform: rotate(-8deg);}33% { transform: rotate(6deg);}35% { transform: rotate(-4deg);}37% { transform: rotate(2deg);}39% { transform: rotate(-1deg);}41% { transform: rotate(1deg);}43% { transform: rotate(0);}100% { transform: rotate(0);}}#sp-wrapper-hovering-img {animation: ring 4s .7s ease-in-out infinite;transform-origin: 50% 4px;}`;
        document.head.appendChild(style);

        const link = document.createElement("a");
        link.href = creative.url;
        link.target = "_blank";
        link.rel = "noopener noreferrer nofollow sponsored";
        setStyle(link, {
            display: "block",
            width: "100%",
            height: "100%",
        });
        const img = document.createElement("img");
        img.src = creative.img;
        setStyle(img, {
            width: "100%",
            height: "100%",
            objectFit: "contain",
            display: "block"
        });

        link.onclick = () => {
            setCapped(config.id_click);
            if (fHovering.isCapped(fHovering.config.id_click, fHovering.config.limit_click)) {
                wrapper.remove();
            }
        };

        link.appendChild(img);
        imgWrap.appendChild(link);
        wrapper.appendChild(closeBtn);
        wrapper.appendChild(imgWrap);
        document.body.appendChild(wrapper);
    }
}

if(fHovering.config.delayInitSecond > 0){
    setTimeout(fHovering.createHoveringBanner, fHovering.config.delayInitSecond * 1000);
}else{
    fHovering.createHoveringBanner();
}